<script setup lang="ts">
import { computed, ref, watch, nextTick, onMounted, onBeforeUnmount } from 'vue'
import { Sparkles, Image as ImageIcon, Images, Video, AudioLines, Layers3, FolderOpen, Monitor, Settings2, ArrowUpRight, ArrowRight, ChevronRight, ChevronDown, Plus, Check, X, Sun, Moon, SlidersHorizontal, ShieldCheck, HardDrive, Download, CircleHelp, Cpu, Zap, WandSparkles, Upload, AlertTriangle, RotateCcw, Pause, Play, CheckCircle2, Info, Search, LoaderCircle, LockKeyhole, Wifi, Smartphone } from '@lucide/vue'
import IdeaArt from './IdeaArt.vue'

type View = 'create' | 'models' | 'library' | 'device' | 'settings'
type Stage = 'initial' | 'preparing' | 'ready' | 'error'
type Modal = '' | 'plan' | 'profiles' | 'adaptations' | 'help' | 'generate' | 'connection' | 'network'
type Profile = { id: string; title: string; tag: string; description: string; family: string; size: string; disk: string; tone: string }
const profiles: Profile[] = [
  { id: 'balanced', title: 'Equilibrado', tag: 'Recomendado', description: 'Buen detalle, sin exigir de más a tu equipo.', family: 'Familia de ejemplo A', size: '5,8 GB', disk: '12 GB', tone: 'green' },
  { id: 'light', title: 'Ligero', tag: 'Menor consumo', description: 'Un punto de partida más sencillo y ligero.', family: 'Familia de ejemplo A', size: '3,2 GB', disk: '8 GB', tone: 'green' },
  { id: 'detail', title: 'Más detalle', tag: 'Experimental', description: 'Podría superar la memoria del equipo de ejemplo.', family: 'Familia de ejemplo B', size: '9,4 GB', disk: '20 GB', tone: 'amber' },
]
const nav = [{ id:'create', label:'Crear', icon:Sparkles },{ id:'models', label:'Modelos', icon:Layers3 },{ id:'library', label:'Biblioteca', icon:FolderOpen }] as const
const utilities = [{ id:'device', label:'Mi equipo', icon:Monitor },{ id:'settings', label:'Ajustes', icon:Settings2 }] as const
const mobileNavigation=[...nav,...utilities]
const view=ref<View>('create'), modal=ref<Modal>(''), stage=ref<Stage>('initial'), profileId=ref('balanced')
const profile=computed(()=>profiles.find(p=>p.id===profileId.value)!)
const previousPrompt=ref<string|null>(null)
const task=ref('image'), prompt=ref(''), format=ref('16:9'), quality=ref('Equilibrio'), style=ref('Natural'), advanced=ref(false)
const theme=ref('system'), search=ref(''), showIncompatible=ref(false), adaptation=ref(''), intensity=ref(0.65), importName=ref(''), reference=ref(''), referenceName=ref('')
const steps=['Comprobar el equipo','Descargar componentes','Preparar el motor','Comprobar que está listo']
const step=ref(0), paused=ref(false), simulation=ref(false), toast=ref(''), scenarios=ref(false), modalEl=ref<HTMLElement|null>(null)
const osDark=ref(true), progress=computed(()=>Math.min(100, Math.round(step.value/steps.length*100)))
const isDark=computed(()=>theme.value==='dark'||theme.value==='system'&&osDark.value)
const filteredProfiles=computed(()=>profiles.filter(p=>(p.title+' '+p.tag).toLowerCase().includes(search.value.toLowerCase())))
const adaptiveOptions=[{id:'film',name:'Luz de película',purpose:'Estilo · luz suave y tonos cálidos',family:'Familia de ejemplo A',trigger:'soft-film-light',class:'film'}, {id:'paper',name:'Tinta y papel',purpose:'Estilo · ilustración con textura',family:'Familia de ejemplo A',trigger:'ink-on-paper',class:'paper'}, {id:'portrait',name:'Retrato editorial',purpose:'Estilo · retratos con luz de estudio',family:'Familia de ejemplo B',trigger:'editorial-portrait',class:'portrait'}]
const compatible=computed(()=>adaptiveOptions.filter(a=>a.family===profile.value.family))
const selectedAdaptation=computed(()=>adaptiveOptions.find(a=>a.id===adaptation.value))
const pageTitles:Record<View,string>={create:'Nueva creación',models:'Modelos',library:'Tu biblioteca',device:'Mi equipo',settings:'Ajustes'}
let timer:ReturnType<typeof setInterval>|undefined, toastTimer:ReturnType<typeof setTimeout>|undefined, restoreFocus:HTMLElement|null=null
let media:MediaQueryList
function notify(message:string){toast.value=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',5000)}
function setTheme(){document.documentElement.dataset.theme=isDark.value?'dark':'light';try{localStorage.setItem('veltria-preview-theme',theme.value)}catch{}}
function examplePrompt(){previousPrompt.value=prompt.value;prompt.value='Un arco monumental en un desierto tranquilo, luz cálida del amanecer, composición cinematográfica.'}
function undoExample(){if(previousPrompt.value!==null){prompt.value=previousPrompt.value;previousPrompt.value=null}}
function focusOptions(){document.querySelector('.creation-settings')?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}
function stopTimer(){clearInterval(timer);timer=undefined}
function beginSimulation(){stage.value='preparing';step.value=0;paused.value=false;simulation.value=true;modal.value='';stopTimer();timer=setInterval(()=>{if(paused.value)return;step.value++;if(step.value>=steps.length){stage.value='ready';stopTimer();notify('Recorrido terminado. No se han instalado ni descargado archivos.')}},1200)}
function setScenario(value:Stage){stopTimer();stage.value=value;simulation.value=value!=='initial';paused.value=false;step.value=value==='ready'?4:1;scenarios.value=false;if(value==='preparing')beginSimulation()}
function selectProfile(p:Profile){if(p.id===profileId.value){modal.value='';return}stopTimer();profileId.value=p.id;stage.value='initial';simulation.value=false;adaptation.value='';modal.value='';notify('Perfil cambiado. Se volverá a revisar su preparación y compatibilidad.')}
function action(){if(stage.value==='initial')modal.value='plan';else if(stage.value==='ready')modal.value='generate';else if(stage.value==='error')beginSimulation();else paused.value=!paused.value}
function uploadReference(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;if(!f.type.startsWith('image/')){notify('Selecciona un archivo de imagen.');return}if(reference.value)URL.revokeObjectURL(reference.value);reference.value=URL.createObjectURL(f);referenceName.value=f.name;task.value='edit'}
function uploadLora(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;importName.value=f.name;notify('Archivo seleccionado. Su compatibilidad no se puede comprobar en este prototipo.')}
function chooseAdaptation(id:string){adaptation.value=adaptation.value===id?'':id;modal.value=''}
function addTrigger(){const t=selectedAdaptation.value?.trigger;if(t&&!prompt.value.includes(t)){prompt.value=(prompt.value.trim()+' '+t).trim();notify('Palabra visible añadida a tu descripción. Puedes editarla o quitarla.')}}
function keyboard(e:KeyboardEvent){if(e.key==='Escape'){modal.value='';scenarios.value=false}if(e.key==='Tab'&&modal.value&&modalEl.value){const elements=[...modalEl.value.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),select,textarea,[tabindex="0"]')].filter(el=>el.getClientRects().length);const first=elements[0],last=elements[elements.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===modalEl.value)){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}
watch(modal,async value=>{document.body.style.overflow=value?'hidden':'';if(value){restoreFocus=document.activeElement as HTMLElement;await nextTick();modalEl.value?.focus()}else{await nextTick();restoreFocus?.focus()}})
watch(view,async()=>{await nextTick();window.scrollTo({top:0})})
watch([isDark,theme],setTheme)
function mediaChange(e:MediaQueryListEvent){osDark.value=e.matches}
onMounted(()=>{try{const saved=localStorage.getItem('veltria-preview-theme');if(saved&&['system','light','dark'].includes(saved))theme.value=saved}catch{}media=window.matchMedia('(prefers-color-scheme: dark)');osDark.value=media.matches;setTheme();document.addEventListener('keydown',keyboard);media.addEventListener('change',mediaChange)})
onBeforeUnmount(()=>{stopTimer();clearTimeout(toastTimer);document.removeEventListener('keydown',keyboard);media?.removeEventListener('change',mediaChange);if(reference.value)URL.revokeObjectURL(reference.value)})
</script>

<template>
  <div class="app-shell" :class="{'creating-view':view==='create'}">
    <aside class="sidebar" :inert="!!modal">
      <a class="brand" href="#" @click.prevent="view='create'" aria-label="Veltria, ir a crear"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M2 6h7l7 14 5-10h-6l2-4h12L17 29z" fill="currentColor"/></svg><span>VELTRIA</span><span class="brand-dot"></span></a>
      <div class="workspace-label">TU ESPACIO CREATIVO</div>
      <nav aria-label="Principal"><button v-for="item in nav" :key="item.id" :class="['nav-item',{active:view===item.id}]" :aria-current="view===item.id?'page':undefined" @click="view=item.id"><component :is="item.icon" :size="19"/><span>{{item.label}}</span><ChevronRight v-if="view===item.id" class="nav-arrow" :size="14"/></button></nav>
      <div class="side-note"><div class="side-orbit"><span></span><span></span><span></span></div><span class="eyebrow">TU IDEA. TU EQUIPO.</span><p>La creatividad es tuya.<br>Del resto nos encargamos.</p></div>
      <div class="sidebar-bottom"><button v-for="item in utilities" :key="item.id" :class="['nav-item',{active:view===item.id}]" @click="view=item.id"><component :is="item.icon" :size="19"/><span>{{item.label}}</span></button><button class="nav-item" @click="modal='help'"><CircleHelp :size="19"/><span>Un poco de ayuda</span><ArrowUpRight :size="14" class="nav-arrow"/></button><div class="sidebar-footer"><span class="version">VELTRIA <span>DESIGN / 02</span></span><button class="icon-button" :aria-label="isDark?'Cambiar a modo claro':'Cambiar a modo oscuro'" @click="theme=isDark?'light':'dark'"><Sun v-if="isDark" :size="17"/><Moon v-else :size="17"/></button></div></div>
    </aside>

    <div class="main-shell" :inert="!!modal">
      <header class="topbar"><a class="mobile-brand" href="#" @click.prevent="view='create'" aria-label="Veltria, ir a crear"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M2 6h7l7 14 5-10h-6l2-4h12L17 29z" fill="currentColor"/></svg><span>VELTRIA</span></a><span class="mobile-demo-badge">PROTOTIPO</span><div class="breadcrumb">Estudio <ChevronRight :size="13"/><span>{{pageTitles[view]}}</span></div><div class="topbar-right"><span class="local-note"><ShieldCheck :size="14"/>Creado para funcionar en tu equipo</span><span class="separator"></span><button class="icon-button mobile-theme-switch" :aria-label="isDark?'Cambiar a modo claro':'Cambiar a modo oscuro'" @click="theme=isDark?'light':'dark'"><Sun v-if="isDark" :size="19"/><Moon v-else :size="19"/></button><button class="icon-button" aria-label="Abrir ajustes" @click="view='settings'"><SlidersHorizontal :size="17"/></button></div></header>
      <div class="mobile-preview-note"><Info :size="14"/><span>Datos de ejemplo. No descarga ni genera.</span></div>
      <main>
        <template v-if="view==='create'">
          <div class="page-heading"><div><div class="eyebrow"><span class="tiny-spark">✦</span> MENOS CONFIGURAR. MÁS CREAR.</div><h1>¿Qué vas a imaginar hoy?</h1><p>Tú pones la idea. Veltria prepara lo necesario.</p></div><div class="private-badge"><LockKeyhole :size="14"/>Tu espacio, en local</div></div>
          <section class="task-grid" aria-label="Qué quieres crear">
            <button :class="['task-card',{selected:task==='image'}]" @click="task='image'" :aria-pressed="task==='image'"><span class="task-icon"><ImageIcon :size="21"/></span><span><strong>Crear una imagen</strong><small>De tus palabras a una imagen</small></span><Check v-if="task==='image'" :size="16" class="task-check"/></button>
            <button :class="['task-card',{selected:task==='edit'}]" @click="task='edit'" :aria-pressed="task==='edit'"><span class="task-icon"><Images :size="21"/></span><span><strong>Transformar una imagen</strong><small>Dale otra vida a una referencia</small></span><Check v-if="task==='edit'" :size="16" class="task-check"/></button>
            <button class="task-card future" disabled><span class="task-icon"><Video :size="21"/></span><span><strong>Crear video</strong><small>Próximamente</small></span></button>
            <button class="task-card future" disabled><span class="task-icon"><AudioLines :size="21"/></span><span><strong>Crear audio</strong><small>Próximamente</small></span></button>
          </section>

          <div class="studio-grid">
            <section class="creation-panel" aria-label="Tu idea">
              <div class="canvas-header"><span><span class="status-dot"></span>UN ESPACIO PARA TU IDEA</span><span class="canvas-corner">{{format}}<span> / </span>{{task==='edit'?'IMAGEN DE REFERENCIA':'NUEVA IMAGEN'}}</span></div>
              <div class="canvas" :class="{ 'has-reference': reference&&task==='edit' }">
                <img v-if="reference&&task==='edit'" :src="reference" :alt="'Referencia: '+referenceName" class="reference-image"/>
                <template v-else><IdeaArt/><div class="canvas-copy"><span class="canvas-kicker">DE UNA PEQUEÑA IDEA</span><h2>A algo extraordinario.</h2><p>{{task==='edit'?'Trae una imagen y decide qué quieres cambiar.':'Un lugar imposible. Una nueva historia. Algo muy tuyo.'}}</p></div></template>
                <label v-if="task==='edit'" class="upload-reference"><Upload :size="16"/>{{reference?'Cambiar referencia':'Elegir imagen de referencia'}}<input type="file" accept="image/*" @change="uploadReference"/></label>
                <div class="canvas-bottom"><span><span class="mini-diamond"></span>{{reference&&task==='edit'?'Solo en esta pestaña':'Ilustración de bienvenida · no es un resultado generado'}}</span><span>01 — ∞</span></div>
              </div>
              <div class="prompt-section"><label for="prompt"><Sparkles :size="16"/>{{task==='edit'?'¿Qué quieres cambiar?':'Describe lo que tienes en mente'}}</label><textarea id="prompt" v-model="prompt" maxlength="2000" :placeholder="task==='edit'?'Por ejemplo: transforma la escena en una ilustración de acuarela…':'Un arco monumental en un desierto tranquilo, luz cálida del amanecer…'" rows="3"></textarea><div class="prompt-bottom"><button class="text-button" @click="examplePrompt"><WandSparkles :size="14"/>Probar una idea</button><button v-if="previousPrompt!==null" class="text-button small" @click="undoExample"><RotateCcw :size="12"/>Deshacer</button><span>{{prompt.length}} / 2000</span></div></div>
            </section>

            <aside class="creation-settings" aria-label="Opciones de creación">
              <section class="profile-section"><div class="section-heading"><h2>Un buen punto de partida</h2><span class="step-label">01</span></div><button class="profile-card" @click="modal='profiles'"><span class="profile-emblem"><Layers3 :size="23"/></span><span><span class="recommendation" :class="{experimental:profile.id==='detail'}"><span class="status-dot"></span>{{profile.tag}}</span><strong>{{profile.title}}</strong></span><ChevronDown :size="16"/></button><p class="helper">{{profile.description}}</p><button class="text-button small" @click="modal='profiles'">Ver otras opciones <ArrowRight :size="12"/></button></section>
              <section class="option-section"><div class="section-heading"><h2>Dale forma</h2><span class="step-label">02</span></div><label class="field-label">Formato</label><div class="format-options" role="group" aria-label="Formato"><button v-for="f in ['16:9','1:1','9:16']" :key="f" :class="{selected:format===f}" :aria-pressed="format===f" @click="format=f"><span :class="['aspect',f==='16:9'?'wide':f==='1:1'?'square':'tall']"></span><span>{{f}}</span></button></div><label class="field-label" for="quality">Prioridad</label><select id="quality" v-model="quality"><option>Equilibrio</option><option>Más rapidez</option><option>Más calidad</option></select><p class="helper compact">Ajustamos los detalles a partir de tu elección.</p></section>
              <section class="option-section"><div class="section-heading"><h2>Tu toque personal</h2><span class="step-label">03</span></div><div class="style-options" role="group" aria-label="Estilo"><button v-for="s in ['Natural','Cine','Ilustración']" :key="s" :class="{selected:style===s}" :aria-pressed="style===s" @click="style=s">{{s}}</button></div><button class="adaptation-button" @click="modal='adaptations'"><Plus v-if="!adaptation" :size="15"/><Check v-else :size="15"/><span>{{selectedAdaptation?.name??'Añadir adaptación'}}</span><span v-if="!adaptation" class="subtle">LoRA</span><ChevronRight :size="14"/></button><p class="helper compact">Estilos o personajes compatibles con tu perfil.</p><div v-if="selectedAdaptation" class="applied-lora"><label for="intensity">Intensidad <strong>{{intensity.toFixed(2)}}</strong></label><input id="intensity" v-model.number="intensity" type="range" min="0" max="1" step="0.05"/><button class="text-button small" @click="addTrigger">Añadir «{{selectedAdaptation.trigger}}» al texto</button><button class="text-button small" @click="adaptation=''">Quitar adaptación</button></div></section>
              <button class="advanced-toggle" :aria-expanded="advanced" @click="advanced=!advanced"><SlidersHorizontal :size="14"/><span>Ajustes avanzados</span><ChevronDown :size="14" :class="{rotated:advanced}"/></button><div v-if="advanced" class="advanced-content"><p>El perfil resolverá estos valores. Aquí podrás afinarlos cuando el motor esté conectado.</p><label>Semilla<input type="text" placeholder="Automática" disabled/></label><p class="small-note">Modelo y receta: {{profile.family}} · ficha conceptual.</p></div>
              <div class="prepare-action"><div v-if="stage==='preparing'" class="inline-progress"><span><LoaderCircle :size="14" class="spin"/>{{paused?'Recorrido en pausa':steps[step]}}</span><strong>{{progress}}%</strong><div class="progress-track"><span :style="{width:progress+'%'}"></span></div><small>Simulación de interfaz · sin descargas</small></div><div v-else-if="stage==='error'" class="recovery-inline"><AlertTriangle :size="16"/><p>La conexión se interrumpió.<br><span>Tu idea sigue aquí. Puedes continuar.</span></p></div><div v-else class="action-note"><CheckCircle2 v-if="stage==='ready'" :size="15"/><Download v-else :size="15"/><span>{{stage==='ready'?'Preparado en el escenario de ejemplo':'Lo preparamos todo por ti'}}</span></div><button class="primary-button full" @click="action"><Pause v-if="stage==='preparing'&&!paused" :size="17"/><Play v-else-if="stage==='preparing'" :size="17"/><RotateCcw v-else-if="stage==='error'" :size="17"/><Sparkles v-else :size="17"/><span>{{stage==='initial'?'Preparar para crear':stage==='ready'?'Crear imagen':stage==='error'?'Reanudar ejemplo':paused?'Continuar recorrido':'Pausar recorrido'}}</span><ArrowRight v-if="stage==='initial'" :size="17"/></button><p>{{stage==='initial'?'Verás qué hace falta antes de empezar.':stage==='ready'?'La generación real aún no está conectada.':'Puedes seguir editando tu descripción.'}}</p></div>
            </aside>
          </div>
          <div class="studio-footnote"><ShieldCheck :size="14"/><span>Tu descripción y archivos se quedan aquí. Sin servicios de generación en la nube.</span><button class="text-button small" @click="modal='help'">Cómo funciona <ArrowUpRight :size="12"/></button></div>
        </template>

        <template v-else-if="view==='models'">
          <div class="page-heading"><div><div class="eyebrow">ELIGE POR LO QUE QUIERES HACER</div><h1>Menos buscar. Más encontrar.</h1><p>Perfiles completos, con todo lo necesario en un mismo lugar.</p></div></div>
          <div class="catalog-toolbar"><span class="pill amber"><ImageIcon :size="14"/>Imagen</span><span class="small-note">Catálogo conceptual · los perfiles no corresponden a paquetes descargables</span></div><div class="profile-grid"><article v-for="p in profiles" :key="p.id" class="catalog-card"><div :class="['catalog-art',p.id]"><Layers3 :size="70" stroke-width=".6"/></div><div class="catalog-copy"><span class="pill" :class="p.tone==='green'?'green':'amber'">{{p.tag}}</span><h2>Imagen · {{p.title}}</h2><p>{{p.description}}</p><details><summary>Modelo y preparación</summary><p>{{p.family}}. Ejemplo de descarga: {{p.size}}. Espacio de ejemplo: {{p.disk}}. Versiones, fuentes y licencia pendientes de un catálogo real.</p></details><button class="secondary-button full" @click="selectProfile(p);view='create'">{{profileId===p.id?'Continuar con este perfil':'Elegir perfil'}}<ArrowRight :size="15"/></button></div></article></div>
        </template>

        <template v-else-if="view==='library'">
          <div class="page-heading"><div><div class="eyebrow">EL PRINCIPIO DE ALGO TUYO</div><h1>Tu biblioteca.</h1><p>Un lugar para volver a tus ideas y seguir explorando.</p></div></div><div class="empty-state"><FolderOpen :size="42" stroke-width="1"/><h2>Aquí vivirán tus creaciones.</h2><p>Este prototipo no genera ni guarda resultados.<br>En la aplicación podrás reutilizar la descripción y los ajustes de cada creación.</p><button class="secondary-button" @click="view='create'">Volver al estudio <ArrowRight :size="15"/></button></div>
        </template>

        <template v-else-if="view==='device'">
          <div class="page-heading"><div><div class="eyebrow">VELTRIA SE ADAPTA A TI</div><h1>Tu equipo, tu punto de partida.</h1><p>Una configuración adecuada para empezar, sin resolver dependencias a mano.</p></div></div><div class="device-banner"><Info :size="18"/><span>Equipo de ejemplo. Este prototipo no detecta el hardware de tu computadora.</span></div><div class="device-grid"><article><Cpu :size="24"/><label>Gráficos de referencia</label><h2>RTX 4050</h2><p>6 GB de VRAM · datos de ejemplo</p></article><article><Monitor :size="24"/><label>Memoria de referencia</label><h2>16 GB</h2><p>RAM del equipo de ejemplo</p></article><article><HardDrive :size="24"/><label>Almacenamiento</label><h2>Por comprobar</h2><p>Lo medirá el servicio local</p></article></div><section class="setup-card"><div class="profile-emblem"><Zap :size="27"/></div><div><span class="eyebrow">NOS ENCARGAMOS DE LA PREPARACIÓN</span><h2>Un motor local, sin complicaciones.</h2><p>Veltria preparará el entorno, los componentes del modelo y los ajustes de un perfil compatible.</p><button class="primary-button" @click="modal='plan'">Preparar este equipo <ArrowRight :size="16"/></button><button class="text-button" @click="modal='connection'">Usar una instalación existente <ChevronRight :size="14"/></button></div></section>
        </template>

        <template v-else>
          <div class="page-heading"><div><div class="eyebrow">A TU MANERA</div><h1>Un espacio que se siente tuyo.</h1><p>Lo esencial a la vista. Los detalles, cuando los necesites.</p></div></div><section class="settings-card"><h2>Apariencia</h2><p>Obsidian. El mismo espacio, con otra luz.</p><div class="theme-options"><button v-for="t in [{id:'dark',name:'Oscuro',icon:Moon},{id:'light',name:'Claro',icon:Sun},{id:'system',name:'Sistema',icon:Monitor}]" :key="t.id" :class="{selected:theme===t.id}" @click="theme=t.id" :aria-pressed="theme===t.id"><component :is="t.icon" :size="24"/><strong>{{t.name}}</strong><Check v-if="theme===t.id" :size="16"/></button></div><p class="small-note">La preferencia de este prototipo se conserva solo en este navegador, si permite almacenamiento local.</p></section><section class="settings-card network-card"><div class="network-card-heading"><h2><Wifi :size="20"/>Red local</h2><span class="pill">Previsto</span></div><p>Usa Veltria desde tu teléfono, tableta u otra computadora de la misma red. El equipo principal hace el trabajo, incluso sin Internet cuando los modelos ya están preparados.</p><div class="network-option"><div><strong>Compartir en mi red local</strong><small>Se activará desde el equipo principal.</small></div><button role="switch" aria-label="Compartir en mi red local" aria-checked="false" disabled class="network-switch"><span></span></button></div><div class="network-pending"><Info :size="15"/><span>Función pendiente. Este prototipo no abre conexiones ni anuncia una dirección de red.</span></div><button class="secondary-button" @click="modal='network'">Ver cómo se conectarán <ArrowRight :size="15"/></button></section><section class="settings-card"><h2>Ubicación de modelos y creaciones</h2><p>En la aplicación, podrás elegir dónde guardar los archivos grandes antes de prepararlos.</p><span class="pill">Disponible al conectar el servicio local</span></section>
        </template>
      </main>
      <footer class="prototype-bar"><span><span class="demo-dot"></span>PROTOTIPO INTERACTIVO <span class="footer-hide">· Datos de ejemplo. No instala ni genera.</span></span><div class="scenario-container"><button @click="scenarios=!scenarios" :aria-expanded="scenarios">Ver escenarios <ChevronDown :size="13"/></button><div v-if="scenarios" class="scenario-menu"><button @click="setScenario('initial');view='create'">Primera preparación</button><button @click="setScenario('preparing');view='create'">Recorrer preparación de ejemplo</button><button @click="setScenario('ready');view='create'">Perfil preparado de ejemplo</button><button @click="setScenario('error');view='create'">Recuperar una interrupción</button></div></div></footer>
    </div>

    <div class="mobile-dock" v-show="!modal">
      <div v-if="view==='create'" class="mobile-action-bar">
        <button class="mobile-profile-link" @click="focusOptions" aria-label="Ir a las opciones de creación"><small>Tu perfil</small><strong>{{profile.title}} <ChevronDown :size="13"/></strong></button>
        <button class="primary-button" @click="action"><Pause v-if="stage==='preparing'&&!paused" :size="17"/><Play v-else-if="stage==='preparing'" :size="17"/><RotateCcw v-else-if="stage==='error'" :size="17"/><Sparkles v-else :size="17"/><span>{{stage==='initial'?'Preparar para crear':stage==='ready'?'Crear imagen':stage==='error'?'Reanudar ejemplo':paused?'Continuar recorrido':'Pausar recorrido'}}</span></button>
      </div>
      <nav class="mobile-nav" aria-label="Navegación móvil"><button v-for="item in mobileNavigation" :key="item.id" :class="{active:view===item.id}" :aria-current="view===item.id?'page':undefined" @click="view=item.id"><component :is="item.icon" :size="20"/><span>{{item.label}}</span></button></nav>
    </div>

    <div v-if="modal" class="modal-backdrop" @click.self="modal=''">
      <section ref="modalEl" :class="['modal',{'wide-modal':['plan','adaptations','profiles','network'].includes(modal)}]" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1">
        <button class="modal-close icon-button" aria-label="Cerrar diálogo" @click="modal=''"><X :size="20"/></button>
        <template v-if="modal==='plan'">
          <div class="modal-eyebrow"><Sparkles :size="15"/>NOS ENCARGAMOS DEL RESTO</div><h2 id="dialog-title">Tu idea necesita un punto de partida.</h2><p class="modal-lead">Prepararemos el perfil <strong>{{profile.title}}</strong> y todo lo necesario para usarlo. Una sola preparación, paso a paso.</p><div class="example-notice"><Info :size="15"/>Plan ilustrativo. No se descargarán ni instalarán archivos.</div><div v-if="profile.id==='detail'" class="warning"><AlertTriangle :size="17"/><p>Perfil experimental: podría superar los 6 GB de VRAM del equipo de ejemplo. <button class="text-button" @click="selectProfile(profiles[0]);modal='plan'">Usar Equilibrado</button></p></div><div class="plan-summary"><div><span>Descarga pendiente</span><strong>{{profile.size}}</strong><small>Valor de ejemplo</small></div><div><span>Espacio necesario</span><strong>{{profile.disk}}</strong><small>Incluye espacio temporal · ejemplo</small></div><div><span>Ubicación</span><strong class="location">Carpeta de Veltria</strong><small>Se elegirá con el servicio local</small></div></div><div class="plan-list"><div v-for="(s,i) in ['Un entorno local preparado','El motor y sus dependencias','El modelo y todos sus componentes','Un perfil listo para tu tarea']" :key="s"><span class="plan-number">0{{i+1}}</span><span>{{s}}</span><Check :size="16"/></div></div><details class="technical-details"><summary>Ver componentes, fuentes y licencia <ChevronDown :size="14"/></summary><p>Esta es una ficha de diseño. El plan real deberá indicar versiones de ComfyUI y del entorno, componentes, fuentes, hashes, licencias y requisitos de acceso. No se autoriza instalar código desde metadatos arbitrarios.</p></details><div class="modal-footer"><span>Tu descripción se conserva.</span><button class="primary-button" @click="beginSimulation">Recorrer preparación de ejemplo <ArrowRight :size="15"/></button></div>
        </template>
        <template v-else-if="modal==='profiles'">
          <div class="modal-eyebrow"><Layers3 :size="15"/>UN PERFIL PARA TU IDEA</div><h2 id="dialog-title">Tú eliges el equilibrio.</h2><p class="modal-lead">Veltria resolverá el modelo y los ajustes. Puedes consultar los detalles.</p><div class="search-field"><Search :size="17"/><input v-model="search" aria-label="Buscar perfiles" placeholder="Buscar una opción…"/></div><div class="profile-picker"><button v-for="p in filteredProfiles" :key="p.id" :class="{chosen:profileId===p.id}" @click="selectProfile(p)"><span class="profile-emblem"><Zap v-if="p.id==='light'" :size="22"/><Layers3 v-else :size="22"/></span><span><strong>{{p.title}} <span :class="['pill',p.tone]">{{p.tag}}</span></strong><small>{{p.description}}</small><small class="technical-family">{{p.family}} · ficha de ejemplo</small></span><Check v-if="profileId===p.id" :size="18"/><ChevronRight v-else :size="18"/></button><p v-if="!filteredProfiles.length" class="helper">No hay perfiles que coincidan con tu búsqueda.</p></div><div class="example-notice"><Info :size="15"/>Perfiles conceptuales. La recomendación real dependerá del equipo, receta y ajustes comprobados.</div>
        </template>
        <template v-else-if="modal==='adaptations'">
          <div class="modal-eyebrow"><WandSparkles :size="15"/>DALE UN TOQUE PROPIO</div><h2 id="dialog-title">Pequeños cambios. Otra personalidad.</h2><p class="modal-lead">Adaptaciones LoRA para el perfil {{profile.title}}. La compatibilidad que ves es un escenario de diseño.</p><div class="adaptation-grid"><button v-for="a in compatible" :key="a.id" :class="['adaptation-card',{chosen:adaptation===a.id}]" @click="chooseAdaptation(a.id)"><div :class="['adaptation-art',a.class]"><Sparkles :size="34" stroke-width="1"/></div><span class="adaptation-info"><span class="pill green">Compatible · ejemplo</span><strong>{{a.name}}</strong><small>{{a.purpose}}</small><span class="small-note">Palabra sugerida: {{a.trigger}}</span></span><Check v-if="adaptation===a.id" :size="18" class="adaptation-check"/></button></div><label class="show-checkbox"><input v-model="showIncompatible" type="checkbox"/>Ver adaptaciones de otras familias</label><div v-if="showIncompatible" class="incompatible-list"><div v-for="a in adaptiveOptions.filter(a=>a.family!==profile.family)" :key="a.id"><AlertTriangle :size="17"/><span><strong>{{a.name}}</strong><small>Requiere {{a.family}}. No se puede aplicar a este perfil.</small></span><span class="pill amber">No compatible</span></div></div><div class="lora-import"><label class="secondary-button"><Upload :size="15"/>Seleccionar un LoRA local<input type="file" accept=".safetensors" @change="uploadLora"/></label><p>Solo selecciona el archivo. No se sube ni se aplica automáticamente.</p></div><div v-if="importName" class="warning"><AlertTriangle :size="16"/><p><strong>{{importName}}</strong><br>Compatibilidad sin identificar. La aplicación real analizará la información disponible antes de ofrecer su activación.</p></div>
        </template>
        <template v-else-if="modal==='generate'"><div class="modal-emblem"><Sparkles :size="26"/></div><h2 id="dialog-title">Tu idea está lista para el siguiente paso.</h2><p class="modal-lead">Has recorrido la nueva interfaz. La generación real se conectará al servicio local y a ComfyUI durante el desarrollo.</p><div class="example-notice"><Info :size="17"/>Este prototipo no ha preparado un motor ni generado una imagen. Tu descripción sigue en el estudio.</div><button class="primary-button full" @click="modal=''">Volver a mi idea <ArrowRight :size="16"/></button></template>
        <template v-else-if="modal==='network'">
          <div class="modal-eyebrow"><Wifi :size="16"/>TU ESTUDIO, EN TU RED</div><h2 id="dialog-title">Tu equipo crea. Tus dispositivos lo controlan.</h2><p class="modal-lead">Abre Veltria desde otro navegador de tu red local. La GPU, los modelos y tus creaciones siguen en el equipo principal.</p>
          <div class="network-devices"><div><Monitor :size="29"/><strong>Equipo principal</strong><span>Motor, modelos y cola</span></div><div><Smartphone :size="29"/><strong>Teléfono o tableta</strong><span>Interfaz y controles</span></div></div>
          <ol class="network-steps"><li><strong>Comparte desde tu equipo</strong><span>Veltria mostrará una dirección local y un QR.</span></li><li><strong>Abre el enlace en el otro dispositivo</strong><span>Conéctalo a la misma red Wi-Fi o al router del equipo.</span></li><li><strong>Autoriza el primer acceso</strong><span>Confirma el dispositivo en el equipo principal. Podrás revocar su acceso después.</span></li></ol>
          <p class="network-offline"><Wifi :size="17"/><span>La red local puede funcionar sin Internet. Mantén el equipo principal encendido y los perfiles preparados.</span></p><div class="example-notice"><Info :size="16"/>Vista del flujo previsto. La conexión LAN todavía no está implementada; no hay un QR ni dispositivos emparejados en este prototipo.</div><button class="secondary-button full" @click="modal=''">Volver a Ajustes</button>
        </template>
        <template v-else-if="modal==='connection'"><div class="modal-eyebrow"><Monitor :size="15"/>PARA QUIEN YA TIENE UN MOTOR</div><h2 id="dialog-title">Usar tu ComfyUI.</h2><p class="modal-lead">Esta será una alternativa avanzada. Veltria comprobará la conexión sin cambiar tu instalación.</p><label class="field-label" for="engine-url">Dirección del motor</label><input id="engine-url" class="text-input" placeholder="http://127.0.0.1:8188" disabled/><div class="example-notice"><Info :size="16"/>La conexión no está implementada en este prototipo. No se contacta ningún motor.</div><button class="secondary-button full" @click="modal='plan'">Prefiero que Veltria lo prepare <ArrowRight :size="16"/></button></template>
        <template v-else><div class="modal-emblem"><ShieldCheck :size="27"/></div><h2 id="dialog-title">Tú creas. Veltria prepara.</h2><p class="modal-lead">Elige una tarea, escribe tu idea y revisa el perfil propuesto. Veltria se encargará de reunir motor, modelos y configuración dentro de los perfiles admitidos.</p><div class="help-list"><p><CheckCircle2 :size="17"/>Una acción para preparar el conjunto.</p><p><CheckCircle2 :size="17"/>Descarga, espacio y decisiones importantes visibles.</p><p><CheckCircle2 :size="17"/>Detalles técnicos cuando quieras consultarlos.</p></div><div class="example-notice"><Info :size="16"/>Este es un prototipo de diseño en Vue. Los perfiles, compatibilidad y preparación son ilustrativos; no hay generación ni detección real.</div><button class="primary-button full" @click="modal=''">Volver al estudio</button></template>
      </section>
    </div>
    <div v-if="toast" class="toast" role="status"><Info :size="17"/><span>{{toast}}</span><button class="icon-button" @click="toast=''" aria-label="Cerrar mensaje"><X :size="15"/></button></div>
  </div>
</template>
